<?php require_once "../db.php";require_role("Student");$uid=current_id();$id=(int)($_GET["id"]??0);$st=$conn->prepare("SELECT h.*,m.title,m.subject FROM practice_history h JOIN practice_material m ON m.id=h.material_id WHERE h.id=? AND h.student_id=?");$st->bind_param("ii",$id,$uid);$st->execute();$d=$st->get_result()->fetch_assoc();if(!$d)die("Analysis not found.");$p=$d["total_questions"]?round($d["score"]/$d["total_questions"]*100,1):0;$level=$p>=75?"Excellent":($p>=60?"Good":($p>=40?"Average":"Needs Improvement"));?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Practice Analysis</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container py-5"><div class="card panel-card"><div class="card-body p-5 text-center"><h2 class="fw-bold"><?=e($d["title"])?></h2><div class="score-circle my-4"><strong><?=$p?>%</strong><span><?=$level?></span></div><div class="row g-3"><div class="col-md-3"><div class="stat-card p-3"><b><?=$d["total_questions"]?></b><br>Total</div></div><div class="col-md-3"><div class="stat-card p-3"><b><?=$d["attempted_questions"]?></b><br>Attempted</div></div><div class="col-md-3"><div class="stat-card p-3"><b class="text-success"><?=$d["correct_answers"]?></b><br>Correct</div></div><div class="col-md-3"><div class="stat-card p-3"><b class="text-danger"><?=$d["wrong_answers"]?></b><br>Wrong</div></div></div><a href="practice_history.php" class="btn btn-primary mt-4">Back to History</a></div></div></div></body></html>
